-- The arrival reminder (Ahmed, 27 Nov 2026 — DECISIONS.md 2026-11-27 «Arrival reminder»). GENERATED by
-- scripts/arrival-reminder-migration.mjs — never edited by hand, never re-run once applied.
--
-- arrival_reminder (Meta-approved, both branch numbers, ar + en; {{1}} first name · {{2}} branch · {{3}} ref ·
-- {{4}} the branch's map link) goes at 16:00 Riyadh (pg_cron wa-arrival-reminder, 13:00 UTC) on the day before arrival,
-- from the branch's own number, for every CONFIRMED booking of a branch whose switch «تذكير الوصول»
-- (settings wa_arrival_reminder, per branch) is on — website, staff and WhatsApp-assistant bookings alike. Skipped: a
-- booking that is not confirmed (also re-checked when it is sent), one with no mobile, and — new here — one confirmed
-- AFTER that day's send time (16:00 Riyadh), so a late cron run or a re-run never reminds a booking made after the send.
-- Every queued reminder is a row of public.whatsapp_messages on the booking (shown in its details: sent / failed /
-- skipped with the reason).
--
-- p_now (default now()) is the moment the tick stands for: its Riyadh date is the send day; tests pass their own.
-- A TEST booking (is_test) is ticked only with p_test; its reminder is built and logged «test» and never sent — except
-- to the system admin's own number (internal.wa_own_test_number), where it is really sent, still logged as a test row.

-- the system admin's own numbers: a «التقارير» recipient (active) or «أرقام التجربة»
create function internal.wa_own_test_number(p_phone text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(p_phone, '') <> '' and (
    exists (select 1 from public.hub_report_recipients r where r.phone = p_phone and r.active)
    or exists (select 1 from public.hub_test_numbers n where n.phone = p_phone))
$$;
revoke execute on function internal.wa_own_test_number(text) from public, anon, authenticated;
grant execute on function internal.wa_own_test_number(text) to postgres, service_role;

drop function public.wa_arrival_tick(boolean);
create function public.wa_arrival_tick(p_test boolean default false, p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_day date := (coalesce(p_now, now()) at time zone 'Asia/Riyadh')::date;
  -- the send time of that day: 16:00 Riyadh
  v_send timestamptz := (v_day + time '16:00') at time zone 'Asia/Riyadh';
  v_n integer;
  v_late integer;
begin
  perform set_config('app.actor', 'scheduler', true);
  insert into public.whatsapp_messages (reservation_id, ref, template, language, branch, status, is_test, trigger)
  select r.id, r.ref, 'arrival_reminder', case when r.locale = 'en' then 'en' else 'ar' end, r.branch, 'queued', r.is_test, 'cron'
    from public.reservations r
   where r.status = 'confirmed' and r.check_in = v_day + 1 and r.is_test = coalesce(p_test, false)
     and nullif(btrim(coalesce(r.phone, '')), '') is not null and internal.branch_switch('wa_arrival_reminder', r.branch)
     and coalesce(r.confirmed_at, r.created_at) <= least(v_send, coalesce(p_now, now()))
  on conflict do nothing;
  get diagnostics v_n = row_count;
  select count(*) into v_late from public.reservations r
   where r.status = 'confirmed' and r.check_in = v_day + 1 and r.is_test = coalesce(p_test, false)
     and coalesce(r.confirmed_at, r.created_at) > least(v_send, coalesce(p_now, now()));
  if v_n > 0 then perform internal.wa_kick(); end if;
  return jsonb_build_object('ok', true, 'queued', v_n, 'confirmed_after_send', v_late, 'day', v_day);
end;
$$;
revoke execute on function public.wa_arrival_tick(boolean, timestamptz) from public, anon, authenticated;
grant execute on function public.wa_arrival_tick(boolean, timestamptz) to service_role;

-- public.wa_claim (20261116200000_guest_hub_departures.sql, copied with the two patches above)
create or replace function public.wa_claim(p_limit integer default 20) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_out jsonb := '[]'::jsonb;
  w record;
  e record;
  v_lim integer := least(greatest(coalesce(p_limit, 20), 1), 100);
  v_code text;
  -- H9: the shared sending limit (judged once, then row by row) and the sends it held back
  v_ls jsonb := internal.hub_limit_state(now());
  v_recent text[] := internal.hub_limit_recent(now());
  v_def integer := 0;
  v_p integer;
begin
  -- the booking templates first (the time of day matters)
  for w in select m.*, r.status as r_status, r.guest_name, r.phone, r.profile_id
             from public.whatsapp_messages m join public.reservations r on r.id = m.reservation_id
            where m.status = 'queued' and m.template in ('arrival_reminder', 'stay_review')
              -- H9: a message held back by the limit is tried again after 10 minutes; the arrival reminders first
              and (m.deferred_at is null or m.deferred_at < now() - interval '10 minutes')
            order by (m.template = 'stay_review'), m.created_at limit v_lim for update of m skip locked loop
    -- H6c: a staff or report number is never a guest (no review, no reminder) — 27 Nov 2026: except a TEST booking's
    -- arrival reminder to the system admin's own number, which is really sent (the end-to-end test)
    if internal.hub_staff_excluded(w.phone) and not (w.is_test and w.template = 'arrival_reminder' and internal.wa_own_test_number(w.phone)) then
      update public.whatsapp_messages set status = 'skipped', error_code = 'staff_number', updated_at = now() where id = w.id;
      continue;
    end if;
    if w.r_status <> 'confirmed'
       or (w.template = 'stay_review' and exists (select 1 from public.guest_profiles g where g.id = w.profile_id and internal.wa_opted_out(g))) then
      update public.whatsapp_messages set status = 'skipped', error_code = case when w.r_status <> 'confirmed' then 'not_confirmed' else 'opted_out' end, updated_at = now() where id = w.id;
      continue;
    end if;
    -- H9: the list of departures already sent this phone its review request for the stay — never twice
    if w.template = 'stay_review' and exists (select 1 from public.hub_departures d where d.phone = w.phone and d.branch_slug = w.branch and not d.is_test
                and d.review_state in ('queued', 'pending', 'accepted', 'sent', 'delivered', 'read') and coalesce(d.review_at, d.updated_at) > now() - interval '36 hours') then
      update public.whatsapp_messages set status = 'skipped', error_code = 'departure_review', updated_at = now() where id = w.id;
      continue;
    end if;
    -- H9: the shared sending limit — arrival reminders priority 2, review requests 3
    v_p := case when w.template = 'arrival_reminder' then 2 else 3 end;
    if not w.is_test and not internal.hub_limit_pass(v_ls, v_recent, w.phone, v_p) then
      update public.whatsapp_messages set deferred_at = now() where id = w.id;
      v_def := v_def + 1;
      continue;
    end if;
    if not w.is_test and not (w.phone = any (v_recent)) then
      v_recent := v_recent || w.phone;
      v_ls := internal.hub_limit_take(v_ls, v_p);
    end if;
    update public.whatsapp_messages set status = 'pending', deferred_at = null, updated_at = now() where id = w.id;
    v_out := v_out || jsonb_build_object('table', 'whatsapp_messages', 'id', w.id, 'template', w.template, 'language', w.language, 'branch', w.branch,
                                         'ref', w.ref, 'name', w.guest_name, 'phone', w.phone, 'is_test', w.is_test,
                                         'send_real', w.is_test and w.template = 'arrival_reminder' and internal.wa_own_test_number(w.phone));
  end loop;
  v_lim := v_lim - jsonb_array_length(v_out);
  if v_lim <= 0 then
    if v_def > 0 then perform internal.hub_limit_deferred(v_def, 'stay'); end if;
    return v_out;
  end if;
  for e in select m.*, g.phone, g.name, internal.eyab_offer_ok(g) as ok, g.marketing_hold_at as held, c.state as c_state, c.vars as c_vars
             from public.eyab_messages m
             left join public.guest_profiles g on g.id = m.profile_id
             left join public.eyab_campaigns c on c.id = m.campaign_id
            where m.status = 'queued' and m.trigger in ('auto', 'campaign')
              and (m.deferred_at is null or m.deferred_at < now() - interval '10 minutes')
            order by m.created_at limit v_lim for update of m skip locked loop
    v_code := case when internal.hub_staff_excluded(e.phone) then 'staff_number' end;
    if v_code is not null then
      null;
    elsif e.template = 'optout_reply' then
      if e.profile_id is null or e.phone is null then v_code := 'not_eligible'; end if;
    elsif e.profile_id is null or not coalesce(e.ok, false) then
      v_code := 'not_eligible';
    elsif e.trigger = 'campaign' and e.c_state is distinct from 'sending' then
      v_code := 'stopped';
    elsif e.template = 'eyab_welcome' and not internal.branch_switch('wa_eyab_welcome', e.branch) then
      v_code := 'switch_off';
    elsif e.template = 'eyab_offer' and e.held is not null then
      v_code := 'held';
    end if;
    if v_code is not null then
      update public.eyab_messages set status = 'skipped', error_code = v_code, updated_at = now() where id = e.id;
      continue;
    end if;
    -- H9: «إياب» (the welcome, the offers) is marketing — the lowest priority of the shared limit
    if e.template in ('eyab_welcome', 'eyab_offer') and not e.is_test and not internal.hub_limit_pass(v_ls, v_recent, e.phone, 4) then
      update public.eyab_messages set deferred_at = now() where id = e.id;
      v_def := v_def + 1;
      continue;
    end if;
    if e.template in ('eyab_welcome', 'eyab_offer') and not e.is_test and not (e.phone = any (v_recent)) then
      v_recent := v_recent || e.phone;
      v_ls := internal.hub_limit_take(v_ls, 4);
    end if;
    update public.eyab_messages set status = 'pending', deferred_at = null, updated_at = now() where id = e.id;
    v_out := v_out || jsonb_build_object('table', 'eyab_messages', 'id', e.id, 'template', e.template, 'language', e.language, 'branch', e.branch,
                                         'campaign_id', e.campaign_id, 'name', e.name, 'phone', e.phone, 'is_test', e.is_test,
                                         'vars', case when e.c_vars is not null then e.c_vars -> e.language end);
  end loop;
  if v_def > 0 then perform internal.hub_limit_deferred(v_def, 'stay_or_marketing'); end if;
  return v_out;
end;
$$;

